CREATE TYPE "OrganizationContractStatus" AS ENUM ('DRAFT','APPROVED','SCHEDULED','ACTIVE','EXPIRED','TERMINATED','CANCELLED');
CREATE TYPE "ContractRevisionType" AS ENUM ('INITIAL','AMENDMENT','RENEWAL');
CREATE TYPE "ContractRevisionStatus" AS ENUM ('DRAFT','APPROVED','SIGNED','CANCELLED');
CREATE TYPE "ContractRenewalMode" AS ENUM ('NONE','MANUAL','AUTO');
CREATE TYPE "ContractBillingCadence" AS ENUM ('MONTHLY','QUARTERLY','ANNUAL');
CREATE TYPE "ContractAdjustmentScope" AS ENUM ('GLOBAL','COMPONENT','CUSTOM_COMPONENT');
CREATE TYPE "ContractAdjustmentType" AS ENUM ('PERCENT_DISCOUNT','FIXED_OVERRIDE','CUSTOM_FIXED_PRICE');
CREATE TYPE "ContractPriceLineSource" AS ENUM ('CATALOG_COMPONENT','CUSTOM_COMPONENT','EXCLUSIVITY_FEE');
CREATE TYPE "ContractTerritoryType" AS ENUM ('ISO_COUNTRY','ISO_SUBDIVISION','REGION','CUSTOM');
CREATE TYPE "ContractExclusivityStatus" AS ENUM ('AGREED','TERMINATED','EXPIRED');
CREATE TYPE "ContractCommitmentType" AS ENUM ('MINIMUM_SPEND','MINIMUM_SEATS','MINIMUM_SITES','MINIMUM_CLIENTS','CUSTOM');
CREATE TYPE "ContractCommitmentPeriod" AS ENUM ('MONTH','QUARTER','YEAR','CONTRACT_TERM');
CREATE TYPE "ContractDocumentType" AS ENUM ('SIGNED_CONTRACT','SIGNED_AMENDMENT','SIGNED_RENEWAL','SUPPORTING_DOCUMENT');

CREATE TABLE "OrganizationContract" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"reference" TEXT NOT NULL,"title" TEXT NOT NULL,"status" "OrganizationContractStatus" NOT NULL DEFAULT 'DRAFT',"isPrimary" BOOLEAN NOT NULL DEFAULT false,"approvedAt" TIMESTAMP(3),"activatedAt" TIMESTAMP(3),"expiredAt" TIMESTAMP(3),"terminatedAt" TIMESTAMP(3),"cancelledAt" TIMESTAMP(3),"lifecycleReason" TEXT,"internalNotes" TEXT,"lockVersion" INTEGER NOT NULL DEFAULT 0,"createdByUserId" TEXT,"createdByDisplayName" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "OrganizationContract_lock_check" CHECK ("lockVersion">=0));
CREATE TABLE "OrganizationContractRevision" ("id" TEXT PRIMARY KEY,"contractId" TEXT NOT NULL,"revisionNumber" INTEGER NOT NULL,"revisionType" "ContractRevisionType" NOT NULL,"status" "ContractRevisionStatus" NOT NULL DEFAULT 'DRAFT',"basedOnRevisionId" TEXT,"priceBookVersionId" TEXT NOT NULL,"currency" CHAR(3) NOT NULL,"effectiveFrom" TIMESTAMP(3) NOT NULL,"effectiveUntil" TIMESTAMP(3),"termStartAt" TIMESTAMP(3) NOT NULL,"termEndAt" TIMESTAMP(3),"renewalMode" "ContractRenewalMode" NOT NULL DEFAULT 'NONE',"renewalTermMonths" INTEGER,"renewalNoticeDays" INTEGER,"renewalTerms" TEXT,"billingCadence" "ContractBillingCadence","approvedAt" TIMESTAMP(3),"signedAt" TIMESTAMP(3),"signedByName" TEXT,"signatureReference" TEXT,"changeSummary" TEXT,"justification" TEXT,"lockVersion" INTEGER NOT NULL DEFAULT 0,"createdByUserId" TEXT,"createdByDisplayName" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ContractRevision_checks" CHECK ("revisionNumber">0 AND "lockVersion">=0 AND "currency" ~ '^[A-Z]{3}$' AND ("effectiveUntil" IS NULL OR "effectiveUntil">"effectiveFrom") AND ("termEndAt" IS NULL OR "termEndAt">"termStartAt") AND ("renewalTermMonths" IS NULL OR "renewalTermMonths">0) AND ("renewalNoticeDays" IS NULL OR "renewalNoticeDays">=0)),CONSTRAINT "ContractRevision_lineage_check" CHECK (("revisionType"='INITIAL' AND "basedOnRevisionId" IS NULL) OR ("revisionType" IN ('AMENDMENT','RENEWAL') AND "basedOnRevisionId" IS NOT NULL)),CONSTRAINT "ContractRevision_signature_check" CHECK (("status"='SIGNED' AND "signedAt" IS NOT NULL) OR ("status"<>'SIGNED' AND "signedAt" IS NULL)));
CREATE TABLE "ContractPricingAdjustment" ("id" TEXT PRIMARY KEY,"contractRevisionId" TEXT NOT NULL,"scope" "ContractAdjustmentScope" NOT NULL,"adjustmentType" "ContractAdjustmentType" NOT NULL,"sourcePriceComponentId" TEXT,"capabilityId" TEXT,"code" TEXT,"label" TEXT,"discountBasisPoints" INTEGER,"overrideAmountMinor" BIGINT,"justification" TEXT NOT NULL,"displayOrder" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ContractAdjustment_values_check" CHECK (("discountBasisPoints" IS NULL OR "discountBasisPoints" BETWEEN 0 AND 10000) AND ("overrideAmountMinor" IS NULL OR "overrideAmountMinor">=0)),CONSTRAINT "ContractAdjustment_matrix_check" CHECK (("scope"='GLOBAL' AND "adjustmentType"='PERCENT_DISCOUNT' AND "sourcePriceComponentId" IS NULL AND "capabilityId" IS NULL AND "discountBasisPoints" IS NOT NULL AND "overrideAmountMinor" IS NULL) OR ("scope"='COMPONENT' AND "adjustmentType"='PERCENT_DISCOUNT' AND "sourcePriceComponentId" IS NOT NULL AND "discountBasisPoints" IS NOT NULL AND "overrideAmountMinor" IS NULL) OR ("scope"='COMPONENT' AND "adjustmentType"='FIXED_OVERRIDE' AND "sourcePriceComponentId" IS NOT NULL AND "discountBasisPoints" IS NULL AND "overrideAmountMinor" IS NOT NULL) OR ("scope"='CUSTOM_COMPONENT' AND "adjustmentType"='CUSTOM_FIXED_PRICE' AND "sourcePriceComponentId" IS NULL AND "capabilityId" IS NOT NULL AND "code" IS NOT NULL AND "label" IS NOT NULL AND "discountBasisPoints" IS NULL AND "overrideAmountMinor" IS NOT NULL)));
CREATE TABLE "ContractPriceSnapshotLine" ("id" TEXT PRIMARY KEY,"contractRevisionId" TEXT NOT NULL,"source" "ContractPriceLineSource" NOT NULL,"sourcePriceComponentId" TEXT,"capabilityId" TEXT,"componentCode" TEXT NOT NULL,"componentName" TEXT NOT NULL,"description" TEXT,"pricingModel" "PricingModel" NOT NULL,"chargeType" "PriceChargeType" NOT NULL,"billingPeriod" "BillingPeriod","metric" "PriceMetric","tierMode" "TierCalculationMode","currency" CHAR(3) NOT NULL,"catalogAmountMinor" BIGINT,"contractAmountMinor" BIGINT,"adjustmentSummary" TEXT,"displayOrder" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ContractSnapshot_check" CHECK ("currency" ~ '^[A-Z]{3}$' AND ("catalogAmountMinor" IS NULL OR "catalogAmountMinor">=0) AND ("contractAmountMinor" IS NULL OR "contractAmountMinor">=0) AND (("source" IN ('CATALOG_COMPONENT','CUSTOM_COMPONENT') AND "capabilityId" IS NOT NULL) OR "source"='EXCLUSIVITY_FEE') AND (("source"='CATALOG_COMPONENT' AND "sourcePriceComponentId" IS NOT NULL) OR ("source"<>'CATALOG_COMPONENT' AND "sourcePriceComponentId" IS NULL))));
CREATE TABLE "ContractPriceSnapshotTier" ("id" TEXT PRIMARY KEY,"snapshotLineId" TEXT NOT NULL,"minimumQuantity" DECIMAL(20,6) NOT NULL,"maximumQuantity" DECIMAL(20,6),"catalogAmountMinor" BIGINT NOT NULL,"contractAmountMinor" BIGINT NOT NULL,"displayOrder" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ContractSnapshotTier_check" CHECK ("minimumQuantity">=0 AND ("maximumQuantity" IS NULL OR "maximumQuantity">"minimumQuantity") AND "catalogAmountMinor">=0 AND "contractAmountMinor">=0));
CREATE TABLE "ContractExclusivity" ("id" TEXT PRIMARY KEY,"contractRevisionId" TEXT NOT NULL,"territoryType" "ContractTerritoryType" NOT NULL,"territoryCode" TEXT,"territoryLabel" TEXT NOT NULL,"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3),"status" "ContractExclusivityStatus" NOT NULL DEFAULT 'AGREED',"hasEconomicImpact" BOOLEAN NOT NULL DEFAULT false,"economicSnapshotLineId" TEXT,"conditions" TEXT,"renewalTerms" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ContractExclusivity_check" CHECK (("endsAt" IS NULL OR "endsAt">"startsAt") AND (("territoryType"='ISO_COUNTRY' AND "territoryCode" ~ '^[A-Z]{2}$') OR ("territoryType"='ISO_SUBDIVISION' AND "territoryCode" ~ '^[A-Z]{2}-[A-Z0-9]{1,3}$') OR "territoryType" IN ('REGION','CUSTOM')) AND (("hasEconomicImpact" AND "economicSnapshotLineId" IS NOT NULL) OR (NOT "hasEconomicImpact" AND "economicSnapshotLineId" IS NULL))));
CREATE TABLE "ContractExclusivitySector" ("exclusivityId" TEXT NOT NULL,"sectorCode" TEXT NOT NULL,"sectorLabel" TEXT NOT NULL,PRIMARY KEY ("exclusivityId","sectorCode"));
CREATE TABLE "ContractExclusivityCapability" ("exclusivityId" TEXT NOT NULL,"capabilityId" TEXT NOT NULL,PRIMARY KEY ("exclusivityId","capabilityId"));
CREATE TABLE "ContractMinimumCommitment" ("id" TEXT PRIMARY KEY,"contractRevisionId" TEXT NOT NULL,"type" "ContractCommitmentType" NOT NULL,"period" "ContractCommitmentPeriod" NOT NULL,"amountMinor" BIGINT,"quantity" DECIMAL(20,6),"currency" CHAR(3),"description" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ContractCommitment_check" CHECK (("type"='MINIMUM_SPEND' AND "amountMinor">=0 AND "quantity" IS NULL AND "currency" ~ '^[A-Z]{3}$') OR ("type" IN ('MINIMUM_SEATS','MINIMUM_SITES','MINIMUM_CLIENTS') AND "quantity">=0 AND "amountMinor" IS NULL AND "currency" IS NULL) OR ("type"='CUSTOM' AND "description" IS NOT NULL)));
CREATE TABLE "OrganizationContractDocument" ("id" TEXT PRIMARY KEY,"contractId" TEXT NOT NULL,"contractRevisionId" TEXT,"type" "ContractDocumentType" NOT NULL,"fileName" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"sizeBytes" INTEGER NOT NULL,"storageKey" TEXT NOT NULL,"sha256" CHAR(64) NOT NULL,"uploadedByUserId" TEXT,"uploadedByName" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ContractDocument_check" CHECK ("sizeBytes">0 AND "sha256" ~ '^[0-9a-f]{64}$'));

CREATE UNIQUE INDEX "OrganizationContract_reference_key" ON "OrganizationContract"("reference"); CREATE INDEX "OrganizationContract_org_status_idx" ON "OrganizationContract"("organizationId","status"); CREATE INDEX "OrganizationContract_org_primary_status_idx" ON "OrganizationContract"("organizationId","isPrimary","status"); CREATE UNIQUE INDEX "OrganizationContract_one_primary_active" ON "OrganizationContract"("organizationId") WHERE "isPrimary" AND "status"='ACTIVE';
CREATE UNIQUE INDEX "ContractRevision_number_key" ON "OrganizationContractRevision"("contractId","revisionNumber"); CREATE UNIQUE INDEX "ContractRevision_one_initial" ON "OrganizationContractRevision"("contractId") WHERE "revisionType"='INITIAL'; CREATE INDEX "ContractRevision_period_idx" ON "OrganizationContractRevision"("contractId","status","effectiveFrom","effectiveUntil");
CREATE UNIQUE INDEX "ContractAdjustment_order_key" ON "ContractPricingAdjustment"("contractRevisionId","displayOrder"); CREATE UNIQUE INDEX "ContractAdjustment_one_global" ON "ContractPricingAdjustment"("contractRevisionId") WHERE "scope"='GLOBAL'; CREATE UNIQUE INDEX "ContractAdjustment_one_component" ON "ContractPricingAdjustment"("contractRevisionId","sourcePriceComponentId") WHERE "scope"='COMPONENT'; CREATE UNIQUE INDEX "ContractAdjustment_custom_code" ON "ContractPricingAdjustment"("contractRevisionId","code") WHERE "scope"='CUSTOM_COMPONENT';
CREATE UNIQUE INDEX "ContractSnapshot_code_key" ON "ContractPriceSnapshotLine"("contractRevisionId","componentCode"); CREATE UNIQUE INDEX "ContractSnapshotTier_order_key" ON "ContractPriceSnapshotTier"("snapshotLineId","displayOrder"); CREATE UNIQUE INDEX "ContractExclusivity_economic_key" ON "ContractExclusivity"("economicSnapshotLineId"); CREATE UNIQUE INDEX "ContractDocument_storage_key" ON "OrganizationContractDocument"("storageKey");

