CREATE FUNCTION protect_contract_revision_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD."status" IN ('SIGNED','CANCELLED') THEN RAISE EXCEPTION 'Signed or cancelled contract revisions are immutable'; END IF; IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Contract revisions cannot be deleted'; END IF; RETURN NEW; END $$;
CREATE TRIGGER "ContractRevision_history_immutable" BEFORE UPDATE OR DELETE ON "OrganizationContractRevision" FOR EACH ROW EXECUTE FUNCTION protect_contract_revision_history();
CREATE FUNCTION protect_contract_child() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE rid TEXT; s "ContractRevisionStatus"; row_data JSONB; BEGIN row_data:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END; rid:=CASE WHEN TG_TABLE_NAME='ContractPriceSnapshotTier' THEN (SELECT "contractRevisionId" FROM "ContractPriceSnapshotLine" WHERE "id"=row_data->>'snapshotLineId') WHEN TG_TABLE_NAME IN ('ContractExclusivitySector','ContractExclusivityCapability') THEN (SELECT "contractRevisionId" FROM "ContractExclusivity" WHERE "id"=row_data->>'exclusivityId') ELSE row_data->>'contractRevisionId' END; SELECT "status" INTO s FROM "OrganizationContractRevision" WHERE "id"=rid; IF s<>'DRAFT' THEN RAISE EXCEPTION 'Contract children require DRAFT revision'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER contract_adjustment_draft BEFORE INSERT OR UPDATE OR DELETE ON "ContractPricingAdjustment" FOR EACH ROW EXECUTE FUNCTION protect_contract_child(); CREATE TRIGGER contract_snapshot_draft BEFORE INSERT OR UPDATE OR DELETE ON "ContractPriceSnapshotLine" FOR EACH ROW EXECUTE FUNCTION protect_contract_child(); CREATE TRIGGER contract_tier_draft BEFORE INSERT OR UPDATE OR DELETE ON "ContractPriceSnapshotTier" FOR EACH ROW EXECUTE FUNCTION protect_contract_child(); CREATE TRIGGER contract_exclusivity_draft BEFORE INSERT OR UPDATE OR DELETE ON "ContractExclusivity" FOR EACH ROW EXECUTE FUNCTION protect_contract_child(); CREATE TRIGGER contract_sector_draft BEFORE INSERT OR UPDATE OR DELETE ON "ContractExclusivitySector" FOR EACH ROW EXECUTE FUNCTION protect_contract_child(); CREATE TRIGGER contract_capability_draft BEFORE INSERT OR UPDATE OR DELETE ON "ContractExclusivityCapability" FOR EACH ROW EXECUTE FUNCTION protect_contract_child(); CREATE TRIGGER contract_commitment_draft BEFORE INSERT OR UPDATE OR DELETE ON "ContractMinimumCommitment" FOR EACH ROW EXECUTE FUNCTION protect_contract_child();
CREATE FUNCTION protect_contract_document() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Contract documents cannot be deleted'; END IF; IF EXISTS(SELECT 1 FROM "OrganizationContractRevision" WHERE "id"=OLD."contractRevisionId" AND "status"='SIGNED') THEN RAISE EXCEPTION 'Signed contract documents are immutable'; END IF; RETURN NEW; END $$; CREATE TRIGGER contract_document_immutable BEFORE UPDATE OR DELETE ON "OrganizationContractDocument" FOR EACH ROW EXECUTE FUNCTION protect_contract_document();
CREATE FUNCTION validate_contract_signature() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW."status"='SIGNED' AND OLD."status"<>'SIGNED' AND EXISTS(SELECT 1 FROM "ContractExclusivity" e LEFT JOIN "ContractPriceSnapshotLine" l ON l."id"=e."economicSnapshotLineId" WHERE e."contractRevisionId"=NEW."id" AND e."hasEconomicImpact" AND (l."id" IS NULL OR l."contractRevisionId"<>NEW."id" OR l."source"<>'EXCLUSIVITY_FEE' OR l."contractAmountMinor" IS NULL OR l."currency"<>NEW."currency")) THEN RAISE EXCEPTION 'Invalid exclusivity economic snapshot'; END IF; RETURN NEW; END $$; CREATE TRIGGER contract_signature_integrity BEFORE UPDATE ON "OrganizationContractRevision" FOR EACH ROW EXECUTE FUNCTION validate_contract_signature();

CREATE FUNCTION prevent_primary_contract_overlap() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE org_id TEXT; parent_id TEXT; from_at TIMESTAMP(3); until_at TIMESTAMP(3); BEGIN
 IF TG_TABLE_NAME='OrganizationContractRevision' THEN
  IF NEW."status"<>'SIGNED' THEN RETURN NEW; END IF;
  parent_id:=NEW."contractId"; from_at:=NEW."effectiveFrom"; until_at:=NEW."effectiveUntil";
  SELECT "organizationId" INTO org_id FROM "OrganizationContract" WHERE "id"=parent_id AND "isPrimary";
  IF org_id IS NULL THEN RETURN NEW; END IF;
 ELSE
  IF NOT NEW."isPrimary" OR NEW."status" NOT IN ('SCHEDULED','ACTIVE') THEN RETURN NEW; END IF;
  org_id:=NEW."organizationId"; parent_id:=NEW."id";
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(org_id,0));
 IF EXISTS (SELECT 1 FROM "OrganizationContract" c JOIN "OrganizationContractRevision" r ON r."contractId"=c."id" WHERE c."organizationId"=org_id AND c."isPrimary" AND c."id"<>parent_id AND c."status" IN ('SCHEDULED','ACTIVE') AND r."status"='SIGNED' AND (TG_TABLE_NAME<>'OrganizationContractRevision' OR tsrange(r."effectiveFrom",r."effectiveUntil",'[)') && tsrange(from_at,until_at,'[)'))) THEN RAISE EXCEPTION 'Primary contract applicability overlaps another contract'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER contract_revision_primary_overlap BEFORE INSERT OR UPDATE ON "OrganizationContractRevision" FOR EACH ROW EXECUTE FUNCTION prevent_primary_contract_overlap();
CREATE TRIGGER contract_primary_overlap BEFORE INSERT OR UPDATE ON "OrganizationContract" FOR EACH ROW EXECUTE FUNCTION prevent_primary_contract_overlap();
